/**
 * Keep everything forever. Nothing is ever auto-deleted.
 */
"never" | 
/**
 * Keep at most `history_limit` unstarred recordings.
 */
"preserve_limit" | "days3" | "weeks2" | "months3" | 
/**
 * Keep for exactly `recording_retention_days` days.
 */
"custom_days"
